def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            version_part, build = v.split('+', 1)
        else:
            version_part = v

        # Split pre-release
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
        else:
            core = version_part
            prerelease = None

        # Parse core version
        major, minor, patch = map(int, core.split('.'))

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
        else:
            prerelease_ids = None

        return (major, minor, patch, prerelease_ids)

    def prerelease_sort_key(prerelease_ids):
        if prerelease_ids is None:
            # No pre-release sorts after pre-release
            return (1,)

        # Pre-release sorts before release
        keys = [0]
        for identifier in prerelease_ids:
            if identifier.isdigit():
                # All-digit identifiers compare numerically
                keys.append((0, int(identifier)))
            else:
                # Other identifiers compare by ASCII order
                keys.append((1, identifier))
        return tuple(keys)

    def sort_key(item):
        index, v = item
        major, minor, patch, prerelease_ids = parse_version(v)
        return (major, minor, patch, prerelease_sort_key(prerelease_ids), index)

    indexed = [(i, v) for i, v in enumerate(versions)]
    sorted_indexed = sorted(indexed, key=sort_key)
    return [v for _, v in sorted_indexed]

